import { useCallback, useEffect, useState } from 'react';
import './App.css';
import Mapa from './components/mapa/Mapa.jsx';
import Sidebar from './components/sidebar/SideBar.jsx';
import Cadastro from './components/cadastro/Cadastro.jsx';

function App() {
  const [showCadastro, setShowCadastro] = useState(false);
  const [locations, setLocations] = useState([]);

  const openCadastro = () => setShowCadastro(true);
  const closeCadastro = () => setShowCadastro(false);

  const fetchLocations = useCallback(() => {
    fetch('http://localhost:8080/api/local/all')
      .then((res) => res.json())
      .then((data) => setLocations(data))
      .catch((err) => console.error(err));
  }, []);

  useEffect(() => {
    fetchLocations();
  }, [fetchLocations]);

  return (
    <div className="">
      <Mapa locations={locations} />
      <Sidebar onAddLocation={openCadastro} />
      {showCadastro && (
        <Cadastro onClose={closeCadastro} onSaved={fetchLocations} />
      )}
    </div>
  );
}

export default App;
